with payload(id,expected_text,reason) as (values ('0c10ae32-1f7c-4997-bd05-5831d555ee53'::uuid,'','Empty scan marker; contains no chapter paragraph.'),('68291fe9-2e3c-4e87-bcbc-765803447902'::uuid,'''Alī, -1291. Maʻānī al-asmāʼ al-ilāhīyah. English. | Tilimsānī,','Incomplete English bibliographic catalogue line; not an Arabic name chapter.'),('5d8f5720-ca36-4bc2-9c00-96a22bfd2a12'::uuid,'al-ilāhīyah.','Incomplete bibliographic title fragment; not a name-specific paragraph.')),
matched as materialized(select p.id,p.entity,p.data original,v.reason from public.platform_records p join payload v on p.id=v.id where p.entity='HolyNameImportedSection' and coalesce(p.data->>'text_content','')=v.expected_text and coalesce(p.data->>'arabic_text','')='' and coalesce(p.data->>'content_role','')=''),
backup as(insert into public.reference_record_backup(record_id,entity,data) select id,entity,original from matched where (select count(*) from matched)=3 on conflict(record_id) do nothing returning record_id),
updated as(update public.platform_records p set data=p.data||jsonb_build_object('content_role','import_metadata','content_classification_note',m.reason),updated_at=now() from matched m where p.id=m.id and (select count(*) from matched)=3 and (select count(*) from backup)>=0 returning (p.data - array['content_role','content_classification_note'])=m.original as source_unchanged)
select count(*) updated_rows,bool_and(source_unchanged) source_unchanged from updated;
